    /// The value in `unit`, for display (`"1.5 km"`); the unit must be of the same kind.
    pub fn in_unit(&self, unit: AnyUnit) -> Result<InUnit<f64, AnyUnit>, KindMismatch> {
        self.convert_to(unit).map(|value| InUnit { value, unit })
    }

